import sys
from functools import lru_cache
sys.setrecursionlimit(100000)

INT=('int',); TOP=('top',); BOT=('bot',); UNIT=('unit',)
def ARR(a,b): return ('arr',a,b)
def AND(a,b): return ('and',a,b)
def OR(a,b): return ('or',a,b)
def PRIM(n): return ('prim',n)
def sz(t):
    if t[0] in ('int','top','bot','unit','prim'): return 1
    return 1+sz(t[1])+sz(t[2])

# syntactic subterm closure
def subterms(t, acc):
    acc.add(t)
    if t[0] in ('arr','and','or'):
        subterms(t[1],acc); subterms(t[2],acc)
    return acc

def wft(env,t):
    k=t[0]
    if k in ('top','bot','int','unit'): return True
    if k=='arr' or k=='and' or k=='or': return wft(env,t[1]) and wft(env,t[2])
    if k=='prim':
        n=t[1]
        return any(a==n for (a,_) in env)
    return False

def dom(env): return set(a for (a,_) in env)

def okenvp(env):
    if env==[]: return True
    (i,A)::rest = env
    if i in dom(rest): return False
    if A==TOP: return okenvp(rest)
    if A[0]=='prim':
        return okenvp(rest) and wft(rest, A) and i not in dom(rest)
    return False

def ordu(t):
    k=t[0]
    if k in ('top','bot','int','unit','prim'): return True
    if k=='arr': return True
    if k=='and': return ordu(t[1]) and ordu(t[2])
    return False

def ordi(t):
    k=t[0]
    if k in ('top','bot','int','unit','prim'): return True
    if k=='arr': return ordu(t[1]) and ordi(t[2])
    if k=='or': return ordi(t[1]) and ordi(t[2])
    return False

# we will compute spli/splu as relations via memoized functions enumerating derivations
# splu A B C: rules
def splu_cases(A, spair):  # spair computes splu sub-relation on subterms
    if A[0]=='or': yield (A[1],A[2])
    if A[0]=='and':
        X,Y=A[1],A[2]
        for (B,C) in spair(X):
            yield (AND(B,Y),AND(C,Y))
        if ordu(X):
            for (B,C) in spair(Y):
                yield (AND(X,B),AND(X,C))

def spli_cases(A, spair_i, spair_u):
    k=A[0]
    if k=='and': yield (A[1],A[2])
    if k=='arr':
        X,B=A[1],A[2]
        for (C,D) in spair_i(B):
            yield (ARR(X,C),ARR(X,D))
        if ordi(B):
            for (P,Q) in spair_u(X):
                yield (ARR(P,B),ARR(Q,B))
    if k=='or':
        X,Y=A[1],A[2]
        for (P,Q) in spair_i(X):
            yield (OR(P,Y),OR(Q,Y))
        if ordu(X):
            for (P,Q) in spair_i(Y):
                yield (OR(X,P),OR(X,Q))

# compute all spli triples over universe U
def build_splits(U):
    # iterate to fixpoint
    US = sorted(U, key=sz)
    spli=set(); splu=set()
    changed=True
    while changed:
        changed=False
        def splu_pairs(A):
            return [(b,c) for (a,b,c) in splu if a==A]
        def spli_pairs(A):
            return [(b,c) for (a,b,c) in spli if a==A]
        for A in US:
            for (B,C) in splu_cases(A, splu_pairs):
                if (A,B,C) not in splu:
                    splu.add((A,B,C)); changed=True
            for (B,C) in spli_cases(A, spli_pairs, splu_pairs):
                if (A,B,C) not in spli:
                    spli.add((A,B,C)); changed=True
    return spli, splu

# algo_sub memoized with measure decreasing
def make_solver(U, spli, splu):
    memo={}
    inside=set()
    def solve(env,A,B):
        key=(tuple(env),A,B)
        if key in memo: return memo[key]
        # measure
        if key in inside:
            # should not happen if measure decreases; return False
            return False
        inside.add(key)
        res=False
        def s(e,a,b):
            return solve(e,a,b)
        # rules
        if A==B and okenvp(env) and wft(env,A):
            res=True
        if not res and A[0]=='prim' and B[0]=='prim' and env:
            (i,Ai)=env[0]; PG=env[1:]
            if okenvp(env):
                if i!=A[1] and s(PG,A,B): res=True
                if Ai==A and s(PG,Ai,B): res=True
        if not res and B==TOP and okenvp(env) and wft(env,A): res=True
        if not res and A==BOT and okenvp(env) and wft(env,B): res=True
        if not res and A[0]=='arr' and B[0]=='arr':
            if s(env,B[1],A[1]) and s(env,A[2],B[2]): res=True
        if not res:
            for (B1,B2) in [(b,c) for (a,b,c) in spli if a==B]:
                if s(env,A,B1) and s(env,A,B2): res=True; break
        if not res:
            for (A1,A2) in [(b,c) for (a,b,c) in spli if a==A]:
                if wft(env,A2) and s(env,A1,B): res=True; break
                if wft(env,A1) and s(env,A2,B): res=True; break
        if not res:
            for (A1,A2) in [(b,c) for (a,b,c) in splu if a==A]:
                if s(env,A1,B) and s(env,A2,B): res=True; break
        if not res:
            for (B1,B2) in [(b,c) for (a,b,c) in splu if a==B]:
                if wft(env,B2) and s(env,A,B1): res=True; break
                if wft(env,B1) and s(env,A,B2): res=True; break
        inside.discard(key)
        memo[key]=res
        return res
    return solve, memo

