def dsub_all(U):
    spli,splu=build_splits(U)
    pairs=set()
    changed=True
    while changed:
        changed=False
        L=list(pairs)
        def add(x,y):
            nonlocal changed
            if (x,y) not in pairs:
                pairs.add((x,y)); changed=True
        for A in U:
            for B in U:
                if A==B: add(A,A)  # refl (wft/okenv nil holds for all)
                if B==TOP: add(A,TOP)
                if A==BOT: add(A,B) if False else add(BOT,B)
        for A in U:
            for C in U:
                for D in U:
                    if (A,C) in pairs:
                        # top/bot handled
                        pass
        # Need efficient closure; iterate all rule combinations
        pairs_list=list(pairs)
        # and intro
        for (A,B) in pairs_list:
            for (A2,C) in pairs_list:
                if A==A2: add(A,AND(B,C))
        # and elim
        for A in U:
            for B in U:
                if (AND(A,B),A) not in pairs: add(AND(A,B),A)
                if (AND(A,B),B) not in pairs: add(AND(A,B),B)
        # arrow
        for A1 in U:
            for A2 in U:
                for B1 in U:
                    for B2 in U:
                        if (B1,A1) in pairs and (A2,B2) in pairs:
                            add(ARR(A1,A2),ARR(B1,B2))
        # or intro/elim
        for A in U:
            for B in U:
                add(A,OR(A,B)); add(B,OR(A,B))
        for A in U:
            for B in U:
                for C in U:
                    if (A,C) in pairs and (B,C) in pairs:
                        add(OR(A,B),C)
        # distributivity
        for A in U:
            for B1 in U:
                for B2 in U:
                    add(AND(ARR(A,B1),ARR(A,B2)),ARR(A,AND(B1,B2)))
        for A1 in U:
            for A2 in U:
