                    add(AND(ARR(A1,B),ARR(A2,B)),ARR(OR(A1,A2),B))
        for A1 in U:
            for A2 in U:
                for B in U:
                    add(AND(OR(A1,B),OR(A2,B)),OR(AND(A1,A2),B))
        # trans closure
        pl=list(pairs)
        for (A,B) in pl:
            for (B2,C) in pl:
                if B==B2: add(A,C)
    return pairs

