                if wft([],A2) and R(A1,B): res=True; break
                if wft([],A1) and R(A2,B): res=True; break
        if not res:
            for (A1,A2) in splu_by.get(A,[]):
                if R(A1,B) and R(A2,B): res=True; break
        if not res:
            for (B1,B2) in splu_by.get(B,[]):
                if wft([],B2) and R(A,B1): res=True; break
                if wft([],B1) and R(A,B2): res=True; break
        rel[(A,B)]=res
    return rel

