    t0=time.time()
    rel=bottom_up(U,spli,splu)
    print(label,"n",len(U),"rel",time.time()-t0, "pairs",sum(rel.values()))
    n=len(U); idx={t:i for i,t in enumerate(U)}
    rows=[0]*n
    for i,A in enumerate(U):
