    pairs=set()
    spli,splu=build_splits(set(U))
    for it in range(maxiter):
        before=len(pairs)
        L=list(pairs)
        add=set()
        for A in U: add.add((A,A)); add.add((A,TOP)); add.add((BOT,A))
        # and intro
        for (A,B) in L:
            for (A2,C) in L:
                if A==A2: add.add((A,AND(B,C)))
        # and elim
        for A in U:
            for B in U:
                add.add((AND(A,B),A)); add.add((AND(A,B),B))
        # arrow
        for A1 in U:
            for A2 in U:
                for B1 in U:
                    for B2 in U:
                        if (B1,A1) in pairs and (A2,B2) in pairs: add.add((ARR(A1,A2),ARR(B1,B2)))
        # or intro
        for A in U:
            for B in U:
                add.add((A,OR(A,B))); add.add((B,OR(A,B)))
        # or elim
        for (A,C) in L:
            for (B,C2) in L:
                if C==C2: add.add((OR(A,B),C))
        # dist
        for A in U:
            for B1 in U:
                for B2 in U:
                    add.add((AND(ARR(A,B1),ARR(A,B2)),ARR(A,AND(B1,B2))))
                    add.add((AND(OR(B1,A),OR(B2,A)),OR(AND(B1,B2),A)))
        for A1 in U:
            for A2 in U:
                for B in U:
                    add.add((AND(ARR(A1,B),ARR(A2,B)),ARR(OR(A1,A2),B)))
        # trans
        for (A,B) in L:
            for (B2,C) in L:
                if B==B2: add.add((A,C))
        pairs|=add
        if len(pairs)==before: break
    return pairs

