def gen_candidates(seeds, rounds=3):
    S=set(seeds)
    base=set(S)
    for r in range(rounds):
        new=set()
        L=list(S)
        for a in L:
            for b in L:
                new.add(AND(a,b)); new.add(OR(a,b)); new.add(ARR(a,b))
        if len(new)>2000: 
            S|= {x for x in new if sz(x)<=6}
        else:
            S|=new
    return S

def prove(A,B,cands,maxdepth=7):
    memo={}
    def go(A,B,d):
        key=(A,B,d)
        if key in memo: return memo[key]
        res=False
        if d<=0:
            memo[key]=False; return False
        # base
        if A==B: res=True
        if not res and B==TOP: res=True
        if not res and A==BOT: res=True
        if not res and A[0]=='arr' and B[0]=='arr':
            res = go(B[1],A[1],d-1) and go(A[2],B[2],d-1)
        if not res and B[0]=='and':
            res = go(A,B[1],d-1) and go(A,B[2],d-1)
        if not res and B[0]=='or':
            res = go(A,B[1],d-1) or go(A,B[2],d-1)
        if not res and A[0]=='and':
            res = go(A[1],B,d-1) or go(A[2],B,d-1)
        if not res and A[0]=='or':
            res = go(A[1],B,d-1) and go(A[2],B,d-1)
        # dist axioms
        if not res and B[0]=='arr' and A[0]=='and':
            # DS_distArr: and(arr X B1)(arr X B2) <: arr X (and B1 B2)
            X1,X2=A[1],A[2]
            if X1[0]=='arr' and X2[0]=='arr' and X1[1]==X2[1]==B[1] and B[2][0]=='and' and B[2][1]==X1[2] and B[2][2]==X2[2]:
                res=True
            # DS_distArrU: and(arr A1 B)(arr A2 B) <: arr (union A1 A2) B
            if X1[0]=='arr' and X2[0]=='arr' and X1[2]==X2[2]==B[2] and B[1][0]=='or' and B[1][1]==X1[1] and B[1][2]==X2[1]:
                res=True
        if not res and A[0]=='and' and B[0]=='or':
            # DS_distOr: and(union A1 B)(union A2 B) <: union(and A1 A2) B
            X1,X2=A[1],A[2]
            if X1[0]=='or' and X2[0]=='or' and X1[2]==X2[2]==B[2] and B[1][0]=='and' and B[1][1]==X1[1] and B[1][2]==X2[1]:
