import sys
from functools import lru_cache
sys.setrecursionlimit(100000)

def T(kind,*args): return (kind,)+args
INT=T('int'); TOP=T('top'); BOT=T('bot'); UNIT=T('unit')
def ARR(a,b): return T('arr',a,b)
def UNI(a,b): return T('uni',a,b)
def AND(a,b): return T('and',a,b)

def size(a):
    if a[0] in ('int','top','bot','unit'): return 1
    return 1+size(a[1])+size(a[2])

@lru_cache(None)
def ordu(a):
    k=a[0]
    if k in ('top','bot','int','unit'): return True
    if k=='arr': return True
    if k=='and': return ordu(a[1]) and ordu(a[2])
    return False

@lru_cache(None)
def ordi(a):
    k=a[0]
    if k in ('top','bot','int','unit'): return True
    if k=='arr': return ordu(a[1]) and ordi(a[2])
    if k=='uni': return ordi(a[1]) and ordi(a[2])
    return False

@lru_cache(None)
def splu_opt(a):
    k=a[0]
    if k=='uni': return (a[1],a[2])
    if k=='and':
        X,Y=a[1],a[2]
        o=splu_opt(X)
        if o: return (AND(o[0],Y), AND(o[1],Y))
        if ordu(X):
            o=splu_opt(Y)
            if o: return (AND(X,o[0]), AND(X,o[1]))
        return None
    return None

@lru_cache(None)
def spli_opt(a):
    k=a[0]
    if k=='and': return (a[1],a[2])
    if k=='arr':
        X,Y=a[1],a[2]
        o=spli_opt(Y)
        if o: return (ARR(X,o[0]), ARR(X,o[1]))
        if ordi(Y):
            o=splu_opt(X)
            if o: return (ARR(o[0],Y), ARR(o[1],Y))
        return None
    if k=='uni':
        X,Y=a[1],a[2]
        o=spli_opt(X)
        if o: return (UNI(o[0],Y), UNI(o[1],Y))
        if ordi(X):
            o=spli_opt(Y)
            if o: return (UNI(X,o[0]), UNI(X,o[1]))
        return None
    return None

def Uf(k,a):
    if k==0: return (a,)
    o=splu_opt(a)
    if o: return Uf(k-1,o[0])+Uf(k-1,o[1])
    return (a,)
def If(k,a):
    if k==0: return (a,)
    o=spli_opt(a)
    if o: return If(k-1,o[0])+If(k-1,o[1])
    return (a,)
def U(a): return Uf(size(a),a)
def I(a): return If(size(a),a)

# wft for empty env, no prims: true for all except prim
def wft(a,G):
    # G list of types for prims not used; no prims
    return True

# cmp G u i, G empty, no prims. Encode G as tuple of (name,type) but skip prims.
@lru_cache(None)
def cmp(G,u,i):
    # only handle empty env or non-prim; G tuple
    if u==TOP: pass
    # C_top
    if i==TOP and wft(u,G): return True
    if u==BOT and wft(i,G): return True
    if i[0]=='uni':
        if wft(i[2],G) and cmp(G,u,i[1]): return True
        if wft(i[1],G) and cmp(G,u,i[2]): return True
    if u[0]=='and':
        if wft(u[2],G) and cmp(G,u[1],i): return True
        if wft(u[1],G) and cmp(G,u[2],i): return True
    if u[0]=='arr' and i[0]=='arr':
        a1,a2=u[1],u[2]; b1,b2=i[1],i[2]
        c1=all(cmp(G,uu,ii) for uu in U(b1) for ii in I(a1))
        c2=all(cmp(G,uu,ii) for uu in U(a2) for ii in I(b2))
        if c1 and c2: return True
    if u==INT and i==INT: return True
    if u==UNIT and i==UNIT: return True
    return False

# enumerate types up to size n
from itertools import product
def gen(n):
    if n==1: return [INT,TOP,BOT,UNIT]
    res=[]
    for k in range(1,n-1):
        l=n-1-k
        if l<1: continue
        for a in gen(k):
            for b in gen(l):
                res += [ARR(a,b),UNI(a,b),AND(a,b)]
    return res

alltypes=[]
for n in range(1,7):
    alltypes += gen(n)
print("num types",len(alltypes))

G=()
bad=[]
for B in alltypes:
    Ub=U(B); Ib=I(B)
    for u in alltypes:
        if not ordu(u): continue
        # under u B: all i in I B cmp u i
        if not all(cmp(G,u,i) for i in Ib): continue
        for i in alltypes:
            if not ordi(i): continue
            if not all(cmp(G,uu,i) for uu in Ub): continue
            if not cmp(G,u,i):
                bad.append((B,u,i))
                print("COUNTEREXAMPLE B,u,i=",B,u,i)
                sys.exit(0)
print("no counterexample up to size 6")
