import sys, functools
sys.setrecursionlimit(100000)

# types: ('int',),('top',),('bot',),('unit',),('arr',a,b),('or',a,b),('and',a,b)
T_INT=('int',); T_TOP=('top',); T_BOT=('bot',); T_UNIT=('unit',)
def arr(a,b): return ('arr',a,b)
def orr(a,b): return ('or',a,b)
def andd(a,b): return ('and',a,b)
def sz(t):
    if t[0] in ('int','top','bot','unit'): return 1
    return 1+sz(t[1])+sz(t[2])

@functools.lru_cache(maxsize=None)
def ordu(t):
    k=t[0]
    if k in ('top','bot','int','unit'): return True
    if k=='arr': return True
    if k=='and': return ordu(t[1]) and ordu(t[2])
    return False

@functools.lru_cache(maxsize=None)
def ordi(t):
    k=t[0]
    if k in ('top','bot','int','unit'): return True
    if k=='arr': return ordu(t[1]) and ordi(t[2])
    if k=='or': return ordi(t[1]) and ordi(t[2])
    return False

@functools.lru_cache(maxsize=None)
def splu_opt(t):
    k=t[0]
    if k=='or': return (t[1],t[2])
    if k=='and':
        X,Y=t[1],t[2]
        o=splu_opt(X)
        if o is not None:
            B1,C1=o; return (andd(B1,Y), andd(C1,Y))
        if ordu(X):
            o2=splu_opt(Y)
            if o2 is not None:
                B2,C2=o2; return (andd(X,B2), andd(X,C2))
        return None
    return None

@functools.lru_cache(maxsize=None)
def spli_opt(t):
    k=t[0]
    if k=='and': return (t[1],t[2])
    if k=='arr':
        X,Y=t[1],t[2]
        o=spli_opt(Y)
        if o is not None:
            C,D=o; return (arr(X,C),arr(X,D))
        if ordi(Y):
            o2=splu_opt(X)
            if o2 is not None:
                P,Q=o2; return (arr(P,Y),arr(Q,Y))
        return None
    if k=='or':
        X,Y=t[1],t[2]
        o=spli_opt(X)
        if o is not None:
            P,Q=o; return (orr(P,Y),orr(Q,Y))
        if ordi(X):
            o2=spli_opt(Y)
            if o2 is not None:
                P,Q=o2; return (orr(X,P),orr(X,Q))
        return None
    return None

@functools.lru_cache(maxsize=None)
def U(t):
    o=splu_opt(t)
    if o is None: return (t,)
    B,C=o; return U(B)+U(C)

@functools.lru_cache(maxsize=None)
def I(t):
    o=spli_opt(t)
    if o is None: return (t,)
    B,C=o; return I(B)+I(C)

@functools.lru_cache(maxsize=None)
def cmp(u,i):
    # ground
    if i[0]=='top': return True
    if u[0]=='bot': return True
    if i[0]=='or':
        return cmp(u,i[1]) or cmp(u,i[2])
    if u[0]=='and':
        return cmp(u[1],i) or cmp(u[2],i)
    if u[0]=='arr' and i[0]=='arr':
        a1,a2=u[1],u[2]; b1,b2=i[1],i[2]
        return all(cmp(x,y) for x in U(b1) for y in I(a1)) and all(cmp(x,y) for x in U(a2) for y in I(b2))
    if u[0]==i[0] and u[0] in ('int','unit'): return True
    return False

def gen_types(maxsize):
    bysize={1:[T_INT,T_TOP,T_BOT,T_UNIT]}
    for s in range(2,maxsize+1):
        lst=[]
        for k in ('arr','or','and'):
            for s1 in range(1,s-1):
                s2=s-1-s1
                if s2<1: continue
                # all types of size s1 and s2
                for a in bysize.get(s1,[]):
                    for b in bysize.get(s2,[]):
                        lst.append((k,a,b))
        bysize[s]=lst
    return bysize

if __name__=='__main__':
    maxB=int(sys.argv[1]) if len(sys.argv)>1 else 6
    maxUI=int(sys.argv[2]) if len(sys.argv)>2 else 4
    by=gen_types(maxB)
    alltypes=[t for s in by for t in by[s]]
    us=[t for t in alltypes if sz(t)<=maxUI and ordu(t)]
    ii=[t for t in alltypes if sz(t)<=maxUI and ordi(t)]
    print("types",len(alltypes),"ordu",len(us),"ordi",len(ii))
    count=0
    for B in alltypes:
        UB=U(B); IB=I(B)
        for u in us:
            # H1
            if not all(cmp(u,j) for j in IB): continue
            for i in ii:
                if not all(cmp(w,i) for w in UB): continue
                if not cmp(u,i):
                    print("COUNTER",B,u,i,"U(B)=",UB,"I(B)=",IB)
                    count+=1
                    if count>20: sys.exit(0)
    print("no counter, checked", len(alltypes)*len(us)*len(ii))
